{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C28"],
      "claim": "Tigecycline has low oral bioavailability in humans, but it is a large, highly polar glycylcycline with multiple ionizable groups; this low-F mechanism does not transfer to the query's lipophilic macrolide scaffold with a basic desosamine sugar.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C05"],
      "claim": "Acarbose has extremely low oral bioavailability (<2%) due to its oligosaccharide nature and minimal intestinal absorption; the query lacks the dense polyhydroxy/polar glycoside character that limits acarbose.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C24"],
      "claim": "Fluticasone propionate has <1% oral bioavailability due to extensive first-pass metabolism; the query is a macrolide antibiotic, not a corticosteroid, and its oral absorption is not subject to the same first-pass inactivation.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a macrolide antibiotic with a lipophilic macrocyclic lactone, a basic desosamine sugar, and an acid-stable oxime ether; macrolides of this type are generally well absorbed orally. The retrieved low-F evidence comes from chemically distinct classes (glycopeptides, aminoglycosides, glycosides, corticosteroids) whose poor oral bioavailability is driven by high polarity, multiple ionizable groups, or extensive first-pass metabolism—features not shared by the query. Thus, despite high assay-transfer scores, the low-F results are not mechanistically transferable, and the query is predicted high.",
  "evidence_gaps": [
    "No direct oral bioavailability data for a macrolide antibiotic was retrieved; all retrieved evidence is from non-macrolide low-F compounds.",
    "The retrieved evidence lacks a structurally analogous macrolide with a known absolute oral bioavailability value."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

